CREATE TABLE players(discord_id text PRIMARY KEY,username text NOT NULL,balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0),level integer NOT NULL DEFAULT 1 CHECK(level>=1),xp bigint NOT NULL DEFAULT 0 CHECK(xp>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_transactions(id bigserial PRIMARY KEY,interaction_id text UNIQUE,from_player_id text REFERENCES players(discord_id),to_player_id text REFERENCES players(discord_id),amount bigint NOT NULL CHECK(amount>0),transaction_type text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX wallet_from_created ON wallet_transactions(from_player_id,created_at DESC);CREATE INDEX wallet_to_created ON wallet_transactions(to_player_id,created_at DESC);CREATE INDEX wallet_type_created ON wallet_transactions(transaction_type,created_at DESC);
CREATE TABLE player_cooldowns(player_id text REFERENCES players(discord_id) ON DELETE CASCADE,command text NOT NULL,available_at timestamptz NOT NULL,PRIMARY KEY(player_id,command));CREATE INDEX cooldown_available ON player_cooldowns(available_at);
CREATE TABLE mines_games(id uuid PRIMARY KEY,player_id text NOT NULL REFERENCES players(discord_id),stake bigint NOT NULL CHECK(stake>0),bomb_count smallint NOT NULL CHECK(bomb_count IN(1,3)),bomb_positions smallint[] NOT NULL,revealed_positions smallint[] NOT NULL DEFAULT '{}',status text NOT NULL CHECK(status IN('active','won','lost','cashed_out')),payout bigint NOT NULL DEFAULT 0 CHECK(payout>=0),created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE UNIQUE INDEX one_active_mines_per_player ON mines_games(player_id) WHERE status='active';CREATE INDEX mines_player_created ON mines_games(player_id,created_at DESC);
CREATE TABLE game_stats(id bigserial PRIMARY KEY,player_id text NOT NULL REFERENCES players(discord_id),game text NOT NULL,result text NOT NULL,stake bigint NOT NULL DEFAULT 0,payout bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX game_stats_player_date ON game_stats(player_id,created_at DESC);
CREATE TABLE items(id text PRIMARY KEY,name text NOT NULL,description text NOT NULL,price bigint NOT NULL CHECK(price>=0),sell_price bigint NOT NULL CHECK(sell_price>=0),kind text NOT NULL DEFAULT 'utility');
CREATE TABLE inventory(player_id text REFERENCES players(discord_id) ON DELETE CASCADE,item_id text REFERENCES items(id),quantity integer NOT NULL CHECK(quantity>=0),PRIMARY KEY(player_id,item_id));
CREATE TABLE trade_offers(id bigserial PRIMARY KEY,from_player text NOT NULL REFERENCES players(discord_id),to_player text NOT NULL REFERENCES players(discord_id),item_id text NOT NULL REFERENCES items(id),quantity integer NOT NULL CHECK(quantity>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','cancelled')),created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX trade_target_pending ON trade_offers(to_player,status,created_at);
CREATE TABLE activity_logs(id bigserial PRIMARY KEY,actor_id text,action text NOT NULL,subject_id text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX activity_created ON activity_logs(created_at DESC);
INSERT INTO items(id,name,description,price,sell_price,kind) VALUES('field_ration','Field Ration','Restores 10 XP after a successful hunt.',100,50,'consumable'),('rusty_sword','Rusty Sword','A starter sword used by the battle command.',500,250,'weapon'),('small_crate','Small Crate','A sealed collectible crate.',250,100,'crate') ON CONFLICT(id) DO NOTHING;
